import java.util.Map;

public class HttpResponseParserTest {
    static int failures = 0;

    static final String OK_RESPONSE =
            "HTTP/1.1 200 OK\r\n"
            + "Content-Type: text/plain\r\n"
            + "Content-Length: 13\r\n"
            + "Set-Cookie: session=abc\r\n"
            + "\r\n"
            + "Hello, world!";

    static final String EMPTY_RESPONSE =
            "HTTP/1.1 404 Not Found\r\n"
            + "Server: study-server\r\n"
            + "\r\n";

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.concurrent.Callable<Object> call) {
        try {
            return call.call();
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    static Object header(String raw, String key) {
        return safe(() -> {
            Map<String, String> headers = HttpResponseParser.headersOf(raw);
            return headers == null ? "headersOf returned null" : headers.get(key);
        });
    }

    public static void main(String[] args) {
        check("statusOf 200 response", 200, safe(() -> HttpResponseParser.statusOf(OK_RESPONSE)));
        check("statusOf 404 response", 404, safe(() -> HttpResponseParser.statusOf(EMPTY_RESPONSE)));
        check("headersOf content-type", "text/plain", header(OK_RESPONSE, "content-type"));
        check("headersOf lowercases mixed-case keys", "session=abc", header(OK_RESPONSE, "set-cookie"));
        check("headersOf stops at the blank line", 3, safe(() -> {
            Map<String, String> headers = HttpResponseParser.headersOf(OK_RESPONSE);
            return headers == null ? "headersOf returned null" : headers.size();
        }));
        check("headersOf on a body-less response", 1, safe(() -> {
            Map<String, String> headers = HttpResponseParser.headersOf(EMPTY_RESPONSE);
            return headers == null ? "headersOf returned null" : headers.size();
        }));
        check("bodyOf returns the text after the blank line", "Hello, world!",
                safe(() -> HttpResponseParser.bodyOf(OK_RESPONSE)));
        check("bodyOf of a response with no body", "",
                safe(() -> HttpResponseParser.bodyOf(EMPTY_RESPONSE)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

