import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

public class HttpResponseParser {

    public static int statusOf(String raw) {
        String firstLine = raw.split("\r\n", -1)[0];
        String[] words = firstLine.split(" ");
        return Integer.parseInt(words[1]);
    }

    public static Map<String, String> headersOf(String raw) {
        Map<String, String> headers = new LinkedHashMap<>();
        String[] lines = raw.split("\r\n", -1);
        for (int i = 1; i < lines.length; i++) {
            String line = lines[i];
            if (line.isEmpty()) {
                break;
            }
            int colon = line.indexOf(':');
            if (colon < 0) {
                continue;
            }
            String key = line.substring(0, colon).trim().toLowerCase(Locale.ROOT);
            String value = line.substring(colon + 1).trim();
            headers.put(key, value);
        }
        return headers;
    }

    public static String bodyOf(String raw) {
        int blankLine = raw.indexOf("\r\n\r\n");
        if (blankLine < 0) {
            return "";
        }
        return raw.substring(blankLine + 4);
    }
}
